import math


def chernoff_bound(n, a):
    # min over t = 0, 0.01, ..., 3.00 of exp(-t a) * cosh(t) ** n
    return min(math.exp(-t * a) * math.cosh(t) ** n for t in (k / 100 for k in range(301)))


def exact_tail(n, a):
    # P(S >= a) for S = 2K - n, with K binomial(n, 1/2)
    k0 = max(0, math.ceil((n + a) / 2))
    return sum(math.comb(n, k) for k in range(k0, n + 1)) / 2 ** n
